-- E4: repair GitHub rule references -- stray URL punctuation and the constant name.
--
-- Two defects, both from the same twelve lines of rule-extractor.ts:
--
--   1. The URL pattern stops at whitespace, so a link written as
--      `(see [rule](https://...yaml))` was stored with its closing brackets.
--      41 of 57 stored references carry stray punctuation. Verified against
--      GitHub: `...yaml)` returns 404, `...yaml` returns 200. Some survive by
--      accident because the paren lands after a `#L4` fragment, which is never
--      sent to the server -- so the "fetch rule content" button works on some
--      references and silently cannot work on others.
--
--   2. The name was the constant 'GitHub Reference'. 57 references, 1 distinct
--      name, while the rule's filename sat unused inside the URL. One report
--      shows 14 identical rows.
--
-- The values below were GENERATED by the shipped module
-- (supabase/functions/_shared/github-reference.ts) rather than by
-- reimplementing its logic in SQL, so the backfill cannot disagree with what
-- the extractor will produce from now on. In particular the bracket-balance
-- rule -- which keeps parentheses that genuinely belong to a GitHub path --
-- is not expressible as a simple trailing-character regex.
--
-- Safe to re-run: rows already carrying the corrected values are rewritten
-- with the same values.

CREATE TABLE IF NOT EXISTS _backup_rules_e4_20260807 AS
SELECT id, rules, now() AS backed_up_at
FROM threat_intel_reports
WHERE EXISTS (
  SELECT 1 FROM jsonb_array_elements(rules) AS ru WHERE ru->>'type' = 'github_reference'
);

