UPDATE threat_intel_reports r
SET rules = (
  SELECT jsonb_agg(
    CASE
      WHEN f.rule_id IS NOT NULL THEN
        -- Merge, so every other key on the rule survives untouched.
        ru || jsonb_build_object(
          'content', f.new_url,
          'name', f.new_name,
          'description', f.new_description
        )
      ELSE ru
    END
    ORDER BY ord   -- rule order is user-visible; preserve it
  )
  FROM jsonb_array_elements(r.rules) WITH ORDINALITY AS t(ru, ord)
  LEFT JOIN fixes f ON f.rule_id = ru->>'id'
)
WHERE EXISTS (
  SELECT 1
  FROM jsonb_array_elements(r.rules) AS ru
  JOIN fixes f2 ON f2.rule_id = ru->>'id'
);

DO $$
DECLARE
  stray int;
  constant_names int;
  lost int;
BEGIN
  SELECT COUNT(*) INTO stray
  FROM threat_intel_reports, jsonb_array_elements(rules) AS ru
  WHERE ru->>'type' = 'github_reference' AND ru->>'content' ~ '[).,;:!?"''>*\]]$';
  IF stray > 0 THEN
    RAISE EXCEPTION 'E4 backfill incomplete: % reference URL(s) still end in prose punctuation', stray;
  END IF;

  SELECT COUNT(*) INTO constant_names
  FROM threat_intel_reports, jsonb_array_elements(rules) AS ru
  WHERE ru->>'type' = 'github_reference' AND ru->>'name' = 'GitHub Reference';
  IF constant_names > 0 THEN
    RAISE EXCEPTION 'E4 backfill incomplete: % reference(s) still named GitHub Reference', constant_names;
  END IF;

  SELECT COUNT(*) INTO lost
  FROM _backup_rules_e4_20260807 b
  JOIN threat_intel_reports r ON r.id = b.id
  WHERE jsonb_array_length(b.rules) <> jsonb_array_length(r.rules);
  IF lost > 0 THEN
    RAISE EXCEPTION 'E4 backfill changed rule counts on % report(s)', lost;
  END IF;
END $$;
